// BlocoEtapaVisual.js
import React from 'react';

export default function BlocoEtapaVisual({ etapas, onChange }) {
  const handleTextoEtapa = (index, novoTexto) => {
    const atualizadas = [...etapas];
    atualizadas[index].mensagem = novoTexto;
    onChange(atualizadas);
  };

  const handleTextoOpcao = (indexEtapa, indexOpcao, novoTexto) => {
    const atualizadas = [...etapas];
    atualizadas[indexEtapa].opcoes[indexOpcao].texto = novoTexto;
    onChange(atualizadas);
  };

  const handleAcaoOpcao = (indexEtapa, indexOpcao, novaAcao) => {
    const atualizadas = [...etapas];
    atualizadas[indexEtapa].opcoes[indexOpcao].acao = novaAcao;
    onChange(atualizadas);
  };

  const handleArquivo = (indexEtapa, indexOpcao, file) => {
    const atualizadas = [...etapas];
    atualizadas[indexEtapa].opcoes[indexOpcao].arquivo = file;
    onChange(atualizadas);
  };

  const handleNomeArquivo = (indexEtapa, indexOpcao, nome) => {
    const atualizadas = [...etapas];
    atualizadas[indexEtapa].opcoes[indexOpcao].nomeArquivo = nome;
    onChange(atualizadas);
  };

  const adicionarEtapa = () => {
    onChange([
      ...etapas,
      { mensagem: '', opcoes: [{ texto: '', acao: 'mensagem', arquivo: null, nomeArquivo: '' }] }
    ]);
  };

  const adicionarOpcao = (indexEtapa) => {
    const atualizadas = [...etapas];
    atualizadas[indexEtapa].opcoes.push({ texto: '', acao: 'mensagem', arquivo: null, nomeArquivo: '' });
    onChange(atualizadas);
  };

  const removerEtapa = (indexEtapa) => {
    const atualizadas = [...etapas];
    atualizadas.splice(indexEtapa, 1);
    onChange(atualizadas);
  };

  const removerOpcao = (indexEtapa, indexOpcao) => {
    const atualizadas = [...etapas];
    atualizadas[indexEtapa].opcoes.splice(indexOpcao, 1);
    onChange(atualizadas);
  };

  return (
    <div className="space-y-6">
      {etapas.map((etapa, i) => (
        <div key={i} className="p-4 border rounded bg-white shadow">
          <div className="flex justify-between items-center mb-2">
            <h3 className="text-lg font-semibold">Etapa {i + 1}</h3>
            <button onClick={() => removerEtapa(i)} className="text-red-500 text-sm">🗑️ Remover Etapa</button>
          </div>

          <textarea
            value={etapa.mensagem}
            onChange={(e) => handleTextoEtapa(i, e.target.value)}
            className="w-full border p-2 rounded mb-4"
            placeholder="Mensagem dessa etapa"
          />

          <div className="space-y-2">
            {etapa.opcoes.map((opcao, j) => (
              <div key={j} className="flex flex-col gap-2">
                <div className="flex items-center space-x-2">
                  <input
                    type="text"
                    value={opcao.texto}
                    onChange={(e) => handleTextoOpcao(i, j, e.target.value)}
                    className="flex-1 border px-2 py-1 rounded"
                    placeholder={`Opção ${j + 1}`}
                  />
                  <select
                    value={opcao.acao}
                    onChange={(e) => handleAcaoOpcao(i, j, e.target.value)}
                    className="border rounded px-2 py-1"
                  >
                    <option value="mensagem">💬 Mensagem</option>
                    <option value="redirecionar">📞 Redirecionar</option>
                    <option value="arquivo">📎 Enviar Arquivo</option>
                  </select>
                  <button onClick={() => removerOpcao(i, j)} className="text-xs text-red-500">🗑️</button>
                </div>

                {opcao.acao === 'arquivo' && (
                  <div className="pl-4 flex flex-col gap-1">
                    <input
                      type="file"
                      onChange={(e) => handleArquivo(i, j, e.target.files[0])}
                      className="border px-2 py-1 rounded"
                    />
                    <input
                      type="text"
                      placeholder="Nome do arquivo (opcional)"
                      value={opcao.nomeArquivo || ''}
                      onChange={(e) => handleNomeArquivo(i, j, e.target.value)}
                      className="border px-2 py-1 rounded"
                    />
                    {opcao.arquivo && (
                      <p className="text-xs text-green-600">Arquivo selecionado: {opcao.arquivo.name}</p>
                    )}
                  </div>
                )}
              </div>
            ))}
          </div>

          <button onClick={() => adicionarOpcao(i)} className="mt-2 text-sm text-blue-600">➕ Adicionar Opção</button>
        </div>
      ))}

      <button
        onClick={adicionarEtapa}
        className="mt-4 px-4 py-2 bg-blue-600 text-white rounded hover:bg-blue-700"
      >
        ➕ Nova Etapa
      </button>
    </div>
  );
}
